import{_ as t,o as a,c as o,a2 as l}from"./chunks/framework.BS0bAV7E.js";const _=JSON.parse('{"title":"宿主侧单元测试","description":"","frontmatter":{},"headers":[],"relativePath":"zh/dev/host-tests.md","filePath":"zh/dev/host-tests.md"}'),s={name:"zh/dev/host-tests.md"};function r(i,e,c,d,h,n){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="宿主侧单元测试" tabindex="-1">宿主侧单元测试 <a class="header-anchor" href="#宿主侧单元测试" aria-label="Permalink to &quot;宿主侧单元测试&quot;">​</a></h1><p><code>make test</code> 运行 <code>tools/run_host_tests.py</code>：它在宿主上编译并执行 <code>tests/host_*.c</code> 中的测试桩，使用它们包含的实际内核源文件。</p><h2 id="运行内容" tabindex="-1">运行内容 <a class="header-anchor" href="#运行内容" aria-label="Permalink to &quot;运行内容&quot;">​</a></h2><p>运行程序从每个测试桩的头文件中提取文档化的 gcc 命令行，重映射重构前的路径（<code>kernel/aead.c</code> -&gt; <code>kernel/crypto/crypto_aead.c</code> 等），使用宿主工具链编译（测试桩要求时使用 ASAN），然后执行它。需要外部固件（openssl 生成的密钥文件）的测试桩会编译但报告 SKIP-FIXTURE 而非失败。</p><p>覆盖率亮点（每个族一个测试桩）：</p><ul><li>crypto：NIST AES/SHA/HMAC 向量、RSA、X.509 解析、AEAD</li><li>tar / gzip / string：lib_* 基础组件</li><li>FAT 结构与 LFN 编码</li><li>multiboot2 解析（包含损坏 MBI 情况，ASAN）</li><li>堆与 VMM 不变性</li></ul><h2 id="何时运行" tabindex="-1">何时运行 <a class="header-anchor" href="#何时运行" aria-label="Permalink to &quot;何时运行&quot;">​</a></h2><p>随时运行。它是反馈循环中最快的信号 - 无需启动，能在几秒内捕获纯逻辑回归（校验和链、头文件对齐、边界）。</p><h2 id="添加测试桩" tabindex="-1">添加测试桩 <a class="header-anchor" href="#添加测试桩" aria-label="Permalink to &quot;添加测试桩&quot;">​</a></h2><ol><li>创建 <code>tests/host_&lt;name&gt;.c</code>，包含标准头文件注释，注明确切的编译命令行（标志 + 包含路径）。</li><li>统计检查次数，按失败数量退出。</li><li><code>make test</code> 会自动拾取它。</li></ol><p>来自 <a href="./../root/CONTRIBUTING.html">CONTRIBUTING.md</a> 的规则：切勿削弱测试以使其通过。如果测试有误，修复测试 <em>并在提交中说明</em>。</p>',11)])])}const m=t(s,[["render",r]]);export{_ as __pageData,m as default};
